"""Configuration for the local (in-process) retrieval backend."""

from enum import Enum
from typing import Literal, Optional

from pydantic import BaseModel, Field

from rasa.builder.document_retrieval.source import ContentType


class ChunkingStrategy(str, Enum):
    """How a documentation page is split into retrievable chunks."""

    WHOLE_PAGE = "whole_page"
    FIXED_TOKEN = "fixed_token"
    BY_HEADING = "by_heading"


class SearchMode(str, Enum):
    """Retrieval mode used at query time."""

    VECTOR = "vector"
    HYBRID = "hybrid"


class ChunkingConfig(BaseModel):
    """Knobs controlling how pages are chunked."""

    strategy: ChunkingStrategy = Field(default=ChunkingStrategy.BY_HEADING)
    chunk_size: int = Field(default=512, description="Approximate tokens per chunk.")
    chunk_overlap: int = Field(default=64, description="Approximate token overlap.")


class EmbedConfig(BaseModel):
    """Knobs controlling embedder model."""

    embed_engine: Literal["fastembed"] = Field(
        default="fastembed",
        description="Embedding engine. fastembed (ONNX) is the default "
        "lower-footprint path; sentence_transformers (torch) is the alternate.",
    )
    embed_model: str = Field(
        default="BAAI/bge-small-en-v1.5",
        description="Embedding model name (valid for both engines).",
    )
    embed_cache_dir: Optional[str] = Field(
        default=None,
        description="Local dir to load/cache the embedding model from. CI "
        "populates this so the runtime never downloads on the query path.",
    )
    index_batch_size: int = Field(
        default=16, description="Batch size when embedding index docs for vector DB."
    )


class LocalRetrievalConfig(BaseModel):
    """Configuration for the local in-process retrieval backend."""

    vectors_artifact_path: Optional[str] = Field(
        default=None,
        description="Path to a prebuilt parquet vector artifact. When set, the "
        "retriever ingests precomputed vectors (no embedding) instead of "
        "building the index from documents.",
    )
    vector_store: Literal["lancedb"] = Field(
        default="lancedb",
        description="Vector store backend. Only 'lancedb' today; swappable seam.",
    )
    embedder: EmbedConfig = Field(default_factory=EmbedConfig)
    top_k: int = Field(default=5, description="Number of chunks to retrieve.")
    index_cache_dir: str = Field(
        default=".retrieval_index",
        description="Directory for cached vector-store tables, keyed by "
        "(embed_engine, embed_model).",
    )
    topic_filter: Optional[str] = Field(
        default=None,
        description="Restrict retrieval to a topic (e.g. 'framework' | 'studio').",
    )
    search_mode: SearchMode = Field(default=SearchMode.VECTOR)

    def chunking_for(self, content_type: ContentType) -> ChunkingConfig:
        """Chunking strategy for a content type.

        Code-defined (not a config knob): markdown splits by heading, everything
        else is indexed whole.
        """
        if content_type is ContentType.MARKDOWN:
            return ChunkingConfig(strategy=ChunkingStrategy.BY_HEADING)
        return ChunkingConfig(strategy=ChunkingStrategy.WHOLE_PAGE)
